import React, { useState } from "react";
import Snake from "./Snake";
import Food from "./Food";

const GameBoard = () => {
  const gridSize = 20; // 定義網格大小
  const [snake, setSnake] = useState([[5, 5], [5, 6]]); // 初始蛇的位置
  const [food, setFood] = useState([10, 10]); // 初始食物位置

  // 渲染棋盤網格背景
  const renderGrid = () => {
    const cells = [];
    for (let row = 0; row < gridSize; row++) {
      for (let col = 0; col < gridSize; col++) {
        const isEven = (row + col) % 2 === 0;
        const cellClass = isEven ? "cell light-green" : "cell dark-green";
        cells.push(
          <div
            key={`${row}-${col}`}
            className={cellClass}
            style={{
              gridRowStart: row + 1,
              gridColumnStart: col + 1,
            }}
          ></div>
        );
      }
    }
    return cells;
  };

  return (
    <div className="board">
      {renderGrid()} {/* 渲染背景棋盤 */}
      <Snake snake={snake} /> {/* 傳遞蛇的數據 */}
      <Food food={food} /> {/* 傳遞食物的位置 */}
    </div>
  );
};

export default GameBoard;
